source='''def transform(grid):
    h, w = len(grid), len(grid[0])
    # Full-width horizontal bars encode a periodic row sequence.
    bars = {}
    for r, row in enumerate(grid):
        if row and row[0] != 0 and all(x == row[0] for x in row):
            bars[r] = row[0]
    if bars:
        period = len(bars)
        seq = {}
        for r, color in bars.items():
            k = r % period
            if k in seq and seq[k] != color:
                raise ValueError("inconsistent horizontal stripe encoding")
            seq[k] = color
        return [[seq[r % period] for _ in range(w)] for r in range(h)]

    # Otherwise, parallel down-right diagonal bars encode colors by c-r residue.
    tracks = {}
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color:
                d = c - r
                if d in tracks and tracks[d] != color:
                    raise ValueError("mixed colors on an encoded diagonal")
                tracks[d] = color
    period = len(tracks)
    seq = {}
    for d, color in tracks.items():
        k = d % period
        if k in seq and seq[k] != color:
            raise ValueError("inconsistent diagonal stripe encoding")
        seq[k] = color
    return [[seq[(c-r) % period] for c in range(w)] for r in range(h)]
'''
